final class QuickSelectEngine {

    private final int[] values;
    private final int targetIndex;
    private final PivotSelector pivotSelector;
    private final SearchBounds searchBounds;

    QuickSelectEngine(int[] values, int targetIndex, PivotSelector pivotSelector) {
        this.values = values;
        this.targetIndex = targetIndex;
        this.pivotSelector = pivotSelector;
        this.searchBounds = SearchBounds.initial(values.length);
    }

    static int select(SelectionRequest request, PivotSelector pivotSelector) {
        return new QuickSelectEngine(request.workingValues(), request.targetIndex(), pivotSelector)
            .select();
    }

    int select() {
        while (searchBounds.isActive()) {
            int partitionIndex = partitionCurrentRange();

            if (partitionIndex == targetIndex) {
                return values[partitionIndex];
            }

            searchBounds.narrowToward(targetIndex, partitionIndex);
        }

        throw new IllegalStateException("Quickselect failed to locate the target index");
    }

    private int partitionCurrentRange() {
        movePivotToEnd();
        int pivot = values[searchBounds.high()];
        int pivotIndex = searchBounds.low();

        for (int i = searchBounds.low(); i < searchBounds.high(); i++) {
            if (values[i] < pivot) {
                swap(i, pivotIndex);
                pivotIndex++;
            }
        }

        swap(searchBounds.high(), pivotIndex);
        return pivotIndex;
    }

    private void movePivotToEnd() {
        swap(
            pivotSelector.selectPivotIndex(values, searchBounds.low(), searchBounds.high()),
            searchBounds.high()
        );
    }

    private void swap(int left, int right) {
        if (left == right) {
            return;
        }

        int temp = values[left];
        values[left] = values[right];
        values[right] = temp;
    }

    private static final class SearchBounds {

        private int low;
        private int high;

        private SearchBounds(int low, int high) {
            this.low = low;
            this.high = high;
        }

        private static SearchBounds initial(int length) {
            return new SearchBounds(0, length - 1);
        }

        private boolean isActive() {
            return low <= high;
        }

        private int low() {
            return low;
        }

        private int high() {
            return high;
        }

        private void narrowToward(int targetIndex, int partitionIndex) {
            if (partitionIndex < targetIndex) {
                low = partitionIndex + 1;
            } else {
                high = partitionIndex - 1;
            }
        }
    }
}

public final class QuickSelect {

    private static final PivotSelector DEFAULT_PIVOT_SELECTOR =
        MedianOfThreePivotSelector.INSTANCE;

    private QuickSelect() {
        // Utility class.
    }

    public static int selectKthSmallest(int[] values, int rank) {
        return SelectionRequest.copying(values, rank).selectWith(DEFAULT_PIVOT_SELECTOR);
    }

    public static int selectKthSmallestInPlace(int[] values, int rank) {
        return SelectionRequest.inPlace(values, rank).selectWith(DEFAULT_PIVOT_SELECTOR);
    }

    public static int kthSmallest(int[] values, int k) {
        return selectKthSmallest(values, k);
    }

    public static void main(String[] args) {
        QuickSelectDemo.main(args);
    }
}

enum MedianOfThreePivotSelector implements PivotSelector {
    INSTANCE;

    @Override
    public int selectPivotIndex(int[] values, int low, int high) {
        int mid = low + (high - low) / 2;

        order(values, low, mid);
        order(values, low, high);
        order(values, mid, high);

        return mid;
    }

    private void order(int[] values, int left, int right) {
        if (values[left] > values[right]) {
            int temp = values[left];
            values[left] = values[right];
            values[right] = temp;
        }
    }
}

import java.util.Arrays;

final class SelectionRequest {

    private final int[] workingValues;
    private final int targetIndex;

    private SelectionRequest(int[] workingValues, int targetIndex) {
        this.workingValues = workingValues;
        this.targetIndex = targetIndex;
    }

    static SelectionRequest copying(int[] values, int rank) {
        validateRank(values, rank);
        return new SelectionRequest(Arrays.copyOf(values, values.length), rank - 1);
    }

    static SelectionRequest inPlace(int[] values, int rank) {
        validateRank(values, rank);
        return new SelectionRequest(values, rank - 1);
    }

    int selectWith(PivotSelector pivotSelector) {
        return QuickSelectEngine.select(this, pivotSelector);
    }

    int[] workingValues() {
        return workingValues;
    }

    int targetIndex() {
        return targetIndex;
    }

    private static void validateRank(int[] values, int rank) {
        if (values == null) {
            throw new IllegalArgumentException("Input array must not be null");
        }

        if (values.length == 0) {
            throw new IllegalArgumentException("Input array must not be empty");
        }

        if (rank < 1 || rank > values.length) {
            throw new IllegalArgumentException(
                "rank must be between 1 and " + values.length + " inclusive");
        }
    }
}

